/**
 * Minimal stand-ins for the CPython exception types that the ported code can
 * raise. Only the pieces the port actually observes are modelled: the class
 * name (used when rendering a traceback) and the message.
 *
 * `pyName` is the dotted name CPython would print on the last line of a
 * traceback, e.g. `ValueError` or `schedule.ScheduleValueError`.
 */
export class PyError extends Error {
  constructor(message) {
    super(message);
    this.name = new.target.name;
  }

  /** Dotted name as CPython would render it in a traceback. */
  get pyName() {
    return this.name;
  }
}

export class PyValueError extends PyError {}

export class PyTypeError extends PyError {}

/** Raised where CPython would raise ValueError from tuple unpacking. */
export function tooManyValuesToUnpack(expected) {
  return new PyValueError(`too many values to unpack (expected ${expected})`);
}

export function notEnoughValuesToUnpack(expected, got) {
  return new PyValueError(
    `not enough values to unpack (expected ${expected}, got ${got})`,
  );
}

