/**
 * Python's notion of whitespace.
 *
 * `str.strip()` (and the leading/trailing tolerance inside `int()`) uses
 * `Py_UNICODE_ISSPACE`, which is *not* the same set as JavaScript's `\s`:
 *
 *   - Python includes the C0 separators U+001C..U+001F and U+0085 (NEL);
 *     JavaScript's `\s` does not.
 *   - JavaScript's `\s` includes U+FEFF (BOM); Python does not treat it as
 *     whitespace.
 *
 * The set below is written out explicitly so the difference stays visible.
 */
const PY_SPACE_CODEPOINTS = new Set(
  [
    0x09, 0x0a, 0x0b, 0x0c, 0x0d, // \t \n \v \f \r
    0x1c, 0x1d, 0x1e, 0x1f, // file/group/record/unit separators
    0x20, // space
    0x85, // NEL
    0xa0, // no-break space
    0x1680, // ogham space mark
    0x2000, 0x2001, 0x2002, 0x2003, 0x2004, 0x2005,
    0x2006, 0x2007, 0x2008, 0x2009, 0x200a,
    0x2028, // line separator
    0x2029, // paragraph separator
    0x202f, // narrow no-break space
    0x205f, // medium mathematical space
    0x3000, // ideographic space
  ],
);

/** True when `ch` (a single code point) is whitespace by Python's rules. */
export function isPySpace(ch) {
  if (typeof ch !== 'string' || ch.length === 0) return false;
  return PY_SPACE_CODEPOINTS.has(ch.codePointAt(0));
}

/** Equivalent of Python's `str.strip()` with no argument. */
export function pyStrip(s) {
  const chars = Array.from(s);
  let start = 0;
  let end = chars.length;
  while (start < end && isPySpace(chars[start])) start += 1;
  while (end > start && isPySpace(chars[end - 1])) end -= 1;
  return chars.slice(start, end).join('');
}

