/**
 * Unicode decimal-digit support.
 *
 * Python's `re` treats `\d` as "anything in General_Category=Nd", and `int()`
 * converts those characters using their Unicode numeric value. JavaScript's
 * `\d` is ASCII-only and `Number()`/`parseInt()` reject non-ASCII digits, so
 * the port needs its own digit handling to stay faithful.
 *
 * Rather than embed a code-point table (which would drift from whatever
 * Unicode version the host Node build ships), the numeric value is derived
 * from the code point at run time. Unicode guarantees that every decimal digit
 * system occupies ten consecutive code points ordered 0..9, so within a
 * maximal run of adjacent Nd code points the value is simply
 * `(cp - runStart) % 10`. That handles the awkward cases where several digit
 * blocks sit back to back with no gap between them, e.g. the five
 * mathematical-digit blocks at U+1D7CE..U+1D7FF.
 */

/** Matches exactly one Unicode decimal digit — Python's `\d`. */
const ND = /^\p{Nd}$/u;

/** True when the single code point `ch` is a Unicode decimal digit. */
export function isDecimalDigit(ch) {
  return typeof ch === 'string' && ND.test(ch);
}

function isNdCodePoint(cp) {
  if (cp < 0 || cp > 0x10ffff) return false;
  // Lone surrogates cannot be Nd and would corrupt fromCodePoint round-trips.
  if (cp >= 0xd800 && cp <= 0xdfff) return false;
  return ND.test(String.fromCodePoint(cp));
}

/** Cache of code point -> numeric value, populated a whole run at a time. */
const valueCache = new Map();

function indexRunContaining(cp) {
  let start = cp;
  while (isNdCodePoint(start - 1)) start -= 1;
  let end = cp;
  while (isNdCodePoint(end + 1)) end += 1;
  for (let c = start; c <= end; c += 1) {
    valueCache.set(c, (c - start) % 10);
  }
}

/**
 * Numeric value 0..9 of a Unicode decimal digit, or `null` if `ch` is not one.
 */
export function decimalValue(ch) {
  if (!isDecimalDigit(ch)) return null;
  const cp = ch.codePointAt(0);
  if (!valueCache.has(cp)) indexRunContaining(cp);
  return valueCache.get(cp);
}

