/**
 * `int(str)` with CPython's parsing rules.
 *
 * The port needs this because `Number()` and `parseInt()` both reject
 * non-ASCII decimal digits, while CPython accepts any Unicode Nd character.
 * The accepted grammar for base 10 is:
 *
 *     [whitespace] [+|-] digit (digit | '_' digit)* [whitespace]
 *
 * Underscores may separate digits but may not lead, trail, or double up.
 */
import { PyValueError, PyTypeError } from './errors.mjs';
import { pyStrip } from './whitespace.mjs';
import { decimalValue, isDecimalDigit } from './digits.mjs';

function invalidLiteral(original) {
  // CPython reports the *unstripped* argument, single-quoted.
  return new PyValueError(
    `invalid literal for int() with base 10: '${original}'`,
  );
}

/**
 * Convert `value` to an integer the way CPython's `int()` would.
 *
 * Numbers are truncated toward zero (CPython's `int(float)`); strings are
 * parsed with the grammar above. Anything else raises TypeError.
 */
export function pyInt(value) {
  if (typeof value === 'number') {
    if (!Number.isFinite(value)) {
      throw new PyValueError(
        `cannot convert ${Number.isNaN(value) ? 'float NaN' : 'float infinity'} to integer`,
      );
    }
    return Math.trunc(value);
  }
  if (typeof value === 'bigint') return Number(value);
  if (typeof value !== 'string') {
    throw new PyTypeError(
      `int() argument must be a string, a bytes-like object or a real number, not '${typeof value}'`,
    );
  }

  const body = pyStrip(value);
  const chars = Array.from(body);
  let i = 0;
  let sign = 1;
  if (chars[i] === '+' || chars[i] === '-') {
    if (chars[i] === '-') sign = -1;
    i += 1;
  }
  if (i >= chars.length) throw invalidLiteral(value);

  let magnitude = 0;
  let previousWasDigit = false;
  let sawDigit = false;
  for (; i < chars.length; i += 1) {
    const ch = chars[i];
    if (ch === '_') {
      // Must sit between two digits.
      if (!previousWasDigit) throw invalidLiteral(value);
      previousWasDigit = false;
      continue;
    }
    if (!isDecimalDigit(ch)) throw invalidLiteral(value);
    magnitude = magnitude * 10 + decimalValue(ch);
    previousWasDigit = true;
    sawDigit = true;
  }
  if (!sawDigit || !previousWasDigit) throw invalidLiteral(value);
  return sign * magnitude;
}

