/**
 * String helpers mirroring the Python constructs used by the argparse port.
 *
 * Widths are measured in code points (Python's `len()` on a `str`), not UTF-16
 * code units, so astral characters do not silently count twice.
 */

/** Python `len(s)` — number of code points. */
export function pyLen(s) {
  let n = 0;
  // eslint-disable-next-line no-unused-vars
  for (const _ of s) n += 1;
  return n;
}

/** Python `'%-*s' % (width, s)` — pad on the right to `width`. */
export function ljust(s, width, fill = ' ') {
  const pad = width - pyLen(s);
  return pad > 0 ? s + fill.repeat(pad) : s;
}

/** Python `'%*s' % (width, s)` — pad on the left to `width`. */
export function rjust(s, width, fill = ' ') {
  const pad = width - pyLen(s);
  return pad > 0 ? fill.repeat(pad) + s : s;
}

/** `' ' * n`. */
export function spaces(n) {
  return n > 0 ? ' '.repeat(n) : '';
}

/** Python `repr()` for the handful of values this port has to render. */
export function pyRepr(value) {
  if (value === null || value === undefined) return 'None';
  if (value === true) return 'True';
  if (value === false) return 'False';
  if (typeof value === 'string') {
    const escaped = value.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    return `'${escaped}'`;
  }
  return String(value);
}

/**
 * Greedy word wrap equivalent to `textwrap.wrap(text, width)` for the
 * single-spaced, hyphen-free help strings this port renders: whitespace runs
 * collapse to one space and words are never broken.
 */
export function wrap(text, width) {
  const words = text.split(/\s+/u).filter(w => w.length > 0);
  if (words.length === 0) return [];
  const lines = [];
  let line = words[0];
  for (const word of words.slice(1)) {
    if (pyLen(line) + 1 + pyLen(word) <= width) {
      line += ` ${word}`;
    } else {
      lines.push(line);
      line = word;
    }
  }
  lines.push(line);
  return lines;
}

