/**
 * argparse's error types.
 *
 * `SystemExit` stands in for Python's builtin: `parser.error()` and the `-h`
 * action both raise it rather than terminating inline, so the entry point owns
 * the single call to `process.exit`.
 */

/** Python's `SystemExit`. */
export class SystemExit extends Error {
  constructor(code = 0) {
    super(`SystemExit: ${code}`);
    this.name = 'SystemExit';
    this.code = code;
  }
}

/**
 * `argparse.ArgumentError` — an error tied to a specific action, rendered as
 * `argument <name>: <message>`.
 */
export class ArgumentError extends Error {
  constructor(argumentName, message) {
    super(argumentName === null || argumentName === undefined
      ? message
      : `argument ${argumentName}: ${message}`);
    this.name = 'ArgumentError';
    this.argumentName = argumentName;
    this.rawMessage = message;
  }
}

