/**
 * argparse actions.
 *
 * `test4.py` only uses the implicit `store` action plus the automatically added
 * `-h/--help`, so those are the two modelled here. `nargs === null` means
 * "consume exactly one argument", which is the case that drives both the
 * `expected one argument` error and the `--a A` metavar in the usage line.
 */
import { SystemExit } from './errors.mjs';

export class Action {
  constructor({
    optionStrings = [],
    dest,
    nargs = null,
    constValue = undefined,
    defaultValue = null,
    type = null,
    choices = null,
    required = false,
    help = null,
    metavar = null,
  }) {
    this.optionStrings = optionStrings;
    this.dest = dest;
    this.nargs = nargs;
    this.constValue = constValue;
    this.defaultValue = defaultValue;
    this.type = type;
    this.choices = choices;
    this.required = required;
    this.help = help;
    this.metavar = metavar;
  }

  // eslint-disable-next-line no-unused-vars
  call(parser, namespace, values, optionString = null) {
    throw new Error('.call() not implemented');
  }
}

/** The default `store` action. */
export class StoreAction extends Action {
  call(parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

/**
 * The `-h/--help` action: prints help to stdout and exits 0. Because it fires
 * the moment the option is seen, `-h` short-circuits the required-argument
 * check — matching the reference, where `-h` alone exits 0 rather than
 * complaining about the three missing options.
 */
export class HelpAction extends Action {
  constructor({ optionStrings, dest = 'help', help = null }) {
    super({ optionStrings, dest, nargs: 0, defaultValue: null, help });
  }

  call(parser) {
    parser.printHelp();
    throw new SystemExit(0);
  }
}

