export class StoreAction extends Action {
  call(parser, namespace, values) {
    namespace[this.dest] = values;
  }
}

/**
 * The `-h/--help` action: prints help to stdout and exits 0. Because it fires
 * the moment the option is seen, `-h` short-circuits the required-argument
 * check — matching the reference, where `-h` alone exits 0 rather than
 * complaining about the three missing options.
 */
export class HelpAction extends Action {
  constructor({ optionStrings, dest = 'help', help = null }) {
    super({ optionStrings, dest, nargs: 0, defaultValue: null, help });
  }

  call(parser) {
    parser.printHelp();
