/**
 * argparse's `HelpFormatter`.
 *
 * The layout is not cosmetic — it has to come out byte-identical, so the column
 * arithmetic follows the original rather than being re-derived:
 *
 *   action_max_length = max(len(invocation)) + current_indent
 *   help_position     = min(action_max_length + 2, max_help_position=24)
 *   action_width      = help_position - current_indent - 2
 *   help_width        = max(width - help_position, 11)
 *
 * For this parser the longest invocation is `-h, --help` (10), so
 * action_max_length = 12, help_position = 14, and action_width = 10. That is
 * why `-h, --help` is followed by exactly two spaces before its help text, and
 * why `--a A` — which has no help text — gets no padding at all.
 */
import { pyLen, ljust, spaces, wrap } from '../py/text.mjs';
import { getTerminalSize } from '../py/shutil.mjs';

/** Collapses three-or-more newline runs, as argparse does before returning. */
const LONG_BREAK = /\n\n\n+/gu;

class Section {
  constructor(formatter, parent, heading = null) {
    this.formatter = formatter;
    this.parent = parent;
    this.heading = heading;
    this.items = [];
  }

  formatHelp() {
    if (this.parent !== null) this.formatter.indent();
    const itemHelp = this.formatter.joinParts(this.items.map(([fn, args]) => fn(...args)));
    if (this.parent !== null) this.formatter.dedent();

    if (!itemHelp) return '';

    let heading = '';
    if (this.heading !== null && this.heading !== undefined) {
      heading = `${spaces(this.formatter.currentIndent)}${this.heading}:\n`;
    }
    return this.formatter.joinParts(['\n', heading, itemHelp, '\n']);
  }
}

export class HelpFormatter {
  constructor({ prog, indentIncrement = 2, maxHelpPosition = 24, width = null }) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.maxHelpPosition = maxHelpPosition;
    // argparse: shutil.get_terminal_size().columns - 2
    this.width = width ?? getTerminalSize().columns - 2;

    this.currentIndent = 0;
    this.level = 0;
    this.actionMaxLength = 0;

    this.rootSection = new Section(this, null);
    this.currentSection = this.rootSection;
  }

  // --- indentation ---------------------------------------------------------

  indent() {
    this.currentIndent += this.indentIncrement;
    this.level += 1;
  }

  dedent() {
    this.currentIndent -= this.indentIncrement;
    this.level -= 1;
  }

  joinParts(parts) {
    return parts.filter(part => part !== null && part !== undefined && part !== '').join('');
  }

  // --- section building ----------------------------------------------------

  addItem(fn, args) {
    this.currentSection.items.push([fn, args]);
  }

  startSection(heading) {
    this.indent();
    const section = new Section(this, this.currentSection, heading);
    this.addItem(() => section.formatHelp(), []);
    this.currentSection = section;
  }

  endSection() {
    this.currentSection = this.currentSection.parent;
    this.dedent();
  }

  addText(text) {
    if (text === null || text === undefined) return;
    this.addItem(t => this.formatText(t), [text]);
  }

  addUsage(usage, actions, prefix = null) {
    this.addItem(
      (u, a, p) => this.formatUsage(u, a, p),
      [usage, actions, prefix],
    );
  }

  addArguments(actions) {
    for (const action of actions) {
      if (action.help === '<SUPPRESS>') continue;
      const invocationLength = pyLen(this.formatActionInvocation(action));
      const actionLength = invocationLength + this.currentIndent;
      this.actionMaxLength = Math.max(this.actionMaxLength, actionLength);
      this.addItem(a => this.formatAction(a), [action]);
    }
  }

