  formatHelp() {
    let help = this.rootSection.formatHelp();
    if (help) {
      help = help.replace(LONG_BREAK, '\n\n');
      help = `${help.replace(/^\n+/u, '').replace(/\n+$/u, '')}\n`;
    }
    return help;
  }

  formatText(text) {
    const indent = spaces(this.currentIndent);
    const textWidth = Math.max(this.width - this.currentIndent, 11);
    const lines = wrap(text, textWidth).map(line => indent + line);
    return `${lines.join('\n')}\n\n`;
  }

