  formatArgs(action) {
    return this.metavarFor(action);
  }

  /** `-h, --help` / `--a A`. */
  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) return this.metavarFor(action);
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return `${action.optionStrings.join(', ')} ${this.formatArgs(action)}`;
  }

  /** The bracketed fragments that make up the usage line. */
  actionUsageParts(actions) {
    const parts = [];
    for (const action of actions) {
      if (action.help === '<SUPPRESS>') continue;
      if (action.optionStrings.length === 0) {
        parts.push(this.formatArgs(action));
        continue;
      }
      const optionString = action.optionStrings[0];
      let part = action.nargs === 0
        ? optionString
        : `${optionString} ${this.formatArgs(action)}`;
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts;
