  formatUsage(usage, actions, prefix) {
    const usagePrefix = prefix ?? 'usage: ';
    const prog = this.prog;
    let rendered;

    if (usage !== null && usage !== undefined) {
      rendered = usage.replace(/%\(prog\)s/gu, prog);
    } else {
      const optionals = actions.filter(a => a.optionStrings.length > 0);
      const positionals = actions.filter(a => a.optionStrings.length === 0);
      const actionUsage = this.actionUsageParts([...optionals, ...positionals]).join(' ');
      rendered = [prog, actionUsage].filter(s => s).join(' ');

      const textWidth = this.width - this.currentIndent;
      if (pyLen(usagePrefix) + pyLen(rendered) > textWidth) {
        const optParts = this.actionUsageParts(optionals);
        const posParts = this.actionUsageParts(positionals);

        const getLines = (parts, indent, linePrefix = null) => {
          const lines = [];
          let line = [];
          let lineLen = (linePrefix !== null ? pyLen(linePrefix) : pyLen(indent)) - 1;
          for (const part of parts) {
            if (lineLen + 1 + pyLen(part) > textWidth && line.length > 0) {
              lines.push(indent + line.join(' '));
              line = [];
              lineLen = pyLen(indent) - 1;
            }
            line.push(part);
            lineLen += 1 + pyLen(part);
          }
          if (line.length > 0) lines.push(indent + line.join(' '));
          if (linePrefix !== null && lines.length > 0) {
            lines[0] = lines[0].slice(indent.length);
          }
          return lines;
        };

        let lines;
        if (pyLen(usagePrefix) + pyLen(prog) <= 0.75 * textWidth) {
          const indent = spaces(pyLen(usagePrefix) + pyLen(prog) + 1);
          if (optParts.length > 0) {
            lines = getLines([prog, ...optParts], indent, usagePrefix);
            lines.push(...getLines(posParts, indent));
          } else if (posParts.length > 0) {
            lines = getLines([prog, ...posParts], indent, usagePrefix);
          } else {
            lines = [prog];
          }
        } else {
          const indent = spaces(pyLen(usagePrefix));
          lines = getLines([...optParts, ...posParts], indent);
          if (lines.length > 1) {
            lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
          }
          lines = [prog, ...lines];
        }
        rendered = lines.join('\n');
      }
    }

    return `${usagePrefix}${rendered}\n\n`;
  }

  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;

    const header = this.formatActionInvocation(action);
    let actionHeader;
    let indentFirst = 0;

    if (!action.help) {
      // No help text: the invocation stands alone, unpadded.
      actionHeader = `${spaces(this.currentIndent)}${header}\n`;
    } else if (pyLen(header) <= actionWidth) {
      actionHeader = `${spaces(this.currentIndent)}${ljust(header, actionWidth)}  `;
      indentFirst = 0;
    } else {
      actionHeader = `${spaces(this.currentIndent)}${header}\n`;
      indentFirst = helpPosition;
    }

    const parts = [actionHeader];
    if (action.help && action.help.trim()) {
      const helpLines = wrap(action.help, helpWidth);
      parts.push(`${spaces(indentFirst)}${helpLines[0]}\n`);
      for (const line of helpLines.slice(1)) {
        parts.push(`${spaces(helpPosition)}${line}\n`);
      }
    } else if (!actionHeader.endsWith('\n')) {
      parts.push('\n');
    }

    return this.joinParts(parts);
  }
}

