/**
 * A focused port of `argparse.ArgumentParser`.
 *
 * The parsing algorithm follows CPython's `_parse_known_args` closely, because
 * the observable edge cases fall out of its internals rather than from any
 * simpler model:
 *
 *   - Each argv entry is first classified into a pattern string of `O`
 *     (looks like an option), `A` (looks like a value) and `-` (the `--`
 *     separator); everything after `--` is forced to `A`.
 *   - An option taking one value matches the pattern `(A)` — with the `-`
 *     characters stripped precisely because `--` may not be swallowed as a
 *     value. That is why `--b -- --c y` reports `argument --b: expected one
 *     argument` rather than treating `--` as `--b`'s value.
 *   - Anything that starts with `-`, is not a known option and looks like a
 *     negative number is reclassified as a value, so `--a -5` sets `a="-5"`.
 *   - The missing-required check lives inside `parse_known_args`, while the
 *     unrecognized-argument check happens afterwards in `parse_args`. Hence a
 *     command line with both faults reports the missing options first.
 */
import path from 'node:path';

import { pyMatch } from '../py/regex.mjs';
import { pyRepr } from '../py/text.mjs';
import { ArgumentError, SystemExit } from './errors.mjs';
import { StoreAction, HelpAction } from './actions.mjs';
import { HelpFormatter } from './help-formatter.mjs';

/** `_get_action_name` — how an action is referred to in error messages. */
function actionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
  if (action.dest !== null && action.dest !== undefined) return action.dest;
  return null;
}

export class ArgumentParser {
  constructor({
    prog = null,
    usage = null,
    description = null,
    epilog = null,
    prefixChars = '-',
    addHelp = true,
    allowAbbrev = true,
  } = {}) {
    // argparse: os.path.basename(sys.argv[0]).
    this.prog = prog ?? path.basename(process.argv[1] ?? 'program');
    this.usage = usage;
    this.description = description;
    this.epilog = epilog;
    this.prefixChars = prefixChars;
    this.allowAbbrev = allowAbbrev;

    this.actions = [];
    this.optionStringActions = new Map();
    /** Declared positional actions; this parser has none. */
    this.positionalActions = [];

    // Groups exist so the help output carries argparse's section headings.
    this.actionGroups = [
      { title: 'positional arguments', actions: this.positionalActions },
      { title: 'options', actions: [] },
    ];

    if (addHelp) {
      this.addArgument(['-h', '--help'], {
        action: 'help',
        help: 'show this help message and exit',
      });
    }
  }

  // --- declaration ---------------------------------------------------------

  /**
   * `add_argument`. Only the keywords `test4.py` uses are honoured; `dest` is
   * derived from the first long option with its prefix characters stripped, and
   * the metavar defaults to the uppercased dest.
   */
  addArgument(names, {
    action = 'store',
    nargs = null,
    type = null,
    required = false,
    help = null,
    metavar = null,
    defaultValue = null,
    choices = null,
  } = {}) {
    const optionStrings = Array.isArray(names) ? names : [names];
    const longOption = optionStrings.find(
      s => s.length > 1 && this.prefixChars.includes(s[0]) && this.prefixChars.includes(s[1]),
    );
    const source = longOption ?? optionStrings[0];
    const dest = source.replace(new RegExp(`^[${this.prefixChars}]+`, 'u'), '')
      .replace(/-/gu, '_');

    const created = action === 'help'
      ? new HelpAction({ optionStrings, dest, help })
      : new StoreAction({
        optionStrings, dest, nargs, type, required, help, metavar, defaultValue, choices,
      });

    this.actions.push(created);
    this.actionGroups[1].actions.push(created);
    for (const optionString of optionStrings) {
      this.optionStringActions.set(optionString, created);
    }
    return created;
  }

  // --- help / usage --------------------------------------------------------

  getFormatter() {
    return new HelpFormatter({ prog: this.prog });
  }

  formatUsage() {
    const formatter = this.getFormatter();
    formatter.addUsage(this.usage, this.actions);
    return formatter.formatHelp();
  }

  formatHelp() {
    const formatter = this.getFormatter();
    formatter.addUsage(this.usage, this.actions);
    formatter.addText(this.description);
    for (const group of this.actionGroups) {
      formatter.startSection(group.title);
      formatter.addArguments(group.actions);
      formatter.endSection();
    }
    formatter.addText(this.epilog);
    return formatter.formatHelp();
  }

  printUsage(stream = process.stdout) {
    stream.write(this.formatUsage());
  }

  printHelp(stream = process.stdout) {
    stream.write(this.formatHelp());
  }

  /** `parser.error()` — usage to stderr, then `prog: error: msg`, exit 2. */
  error(message) {
    this.printUsage(process.stderr);
    process.stderr.write(`${this.prog}: error: ${message}\n`);
    throw new SystemExit(2);
  }

  // --- classification ------------------------------------------------------

  /** argparse's `_negative_number_matcher`. */
  looksLikeNegativeNumber(argString) {
    return pyMatch(String.raw`^-\d+$|^-\d*\.\d+$`, argString) !== null;
  }

  /** True when any declared option itself looks like a negative number. */
  get hasNegativeNumberOptionals() {
    return [...this.optionStringActions.keys()].some(
      s => this.looksLikeNegativeNumber(s),
    );
  }

  /** `_get_option_tuples` — abbreviation and `-xVALUE` resolution. */
  getOptionTuples(argString) {
    const result = [];
    const chars = this.prefixChars;

    if (chars.includes(argString[0]) && chars.includes(argString[1])) {
      if (this.allowAbbrev) {
