    const positionals = [...this.positionalActions];

    const takeAction = (action, argumentStrings, optionString = null) => {
      seenActions.add(action);
      const argumentValues = this.getValues(action, argumentStrings);
      action.call(this, namespace, argumentValues, optionString);
    };

    const consumeOptional = startIndex => {
      let [action, optionString, explicitArg] = optionStringIndices.get(startIndex);
      const actionTuples = [];
      let stop = startIndex;

      for (;;) {
        if (action === null) {
          extras.push(argStrings[startIndex]);
          return startIndex + 1;
        }
        if (explicitArg !== null && explicitArg !== undefined) {
          const argCount = this.matchArgument(action, 'A');
          if (argCount === 0 && !this.prefixChars.includes(optionString[1])
            && explicitArg !== '') {
            // `-xyz` where `-x` takes no value: peel off `-y` and continue.
            actionTuples.push([action, [], optionString]);
            const char = optionString[0];
            optionString = char + explicitArg[0];
            const newExplicitArg = explicitArg.slice(1) || null;
            if (this.optionStringActions.has(optionString)) {
