            } else {
              throw new ArgumentError(
                actionName(action), `ignored explicit argument ${pyRepr(explicitArg)}`,
              );
            }
          } else if (argCount === 1) {
            stop = startIndex + 1;
            actionTuples.push([action, [explicitArg], optionString]);
            break;
          } else {
            throw new ArgumentError(
              actionName(action), `ignored explicit argument ${pyRepr(explicitArg)}`,
            );
          }
        } else {
          const start = startIndex + 1;
          const argCount = this.matchArgument(action, argStringsPattern.slice(start));
          stop = start + argCount;
          actionTuples.push([action, argStrings.slice(start, stop), optionString]);
          break;
        }
      }

      for (const [a, values, optString] of actionTuples) {
        takeAction(a, values, optString);
      }
      return stop;
    };

    const consumePositionals = startIndex => {
      // This parser declares no positionals, so nothing is ever consumed here
      // and every leftover argv entry becomes an unrecognized extra.
      let index = startIndex;
      const counts = [];
      for (const action of positionals) {
        const count = this.matchArgument(action, argStringsPattern.slice(index));
        counts.push(count);
        takeAction(action, argStrings.slice(index, index + count));
        index += count;
      }
      positionals.splice(0, counts.length);
      return index;
    };

    let startIndex = 0;
    const maxOptionStringIndex = optionStringIndices.size > 0
      ? Math.max(...optionStringIndices.keys())
      : -1;

    while (startIndex <= maxOptionStringIndex) {
      const nextOptionStringIndex = Math.min(
        ...[...optionStringIndices.keys()].filter(index => index >= startIndex),
      );
      if (startIndex !== nextOptionStringIndex) {
        const positionalsEndIndex = consumePositionals(startIndex);
        if (positionalsEndIndex > startIndex) {
          startIndex = positionalsEndIndex;
          continue;
        }
        startIndex = positionalsEndIndex;
      }
      if (startIndex !== nextOptionStringIndex) {
        extras.push(...argStrings.slice(startIndex, nextOptionStringIndex));
        startIndex = nextOptionStringIndex;
      }
      startIndex = consumeOptional(startIndex);
    }

    const stopIndex = consumePositionals(startIndex);
    extras.push(...argStrings.slice(stopIndex));

    const requiredActions = [];
    for (const action of this.actions) {
      if (!seenActions.has(action) && action.required) {
        requiredActions.push(actionName(action));
      }
    }
    if (requiredActions.length > 0) {
      this.error(`the following arguments are required: ${requiredActions.join(', ')}`);
    }

    return [namespace, extras];
  }
