/**
 * A focused port of `argparse.ArgumentParser`.
 *
 * The parsing algorithm follows CPython's `_parse_known_args` closely, because
 * the observable edge cases fall out of its internals rather than from any
 * simpler model:
 *
 *   - Each argv entry is first classified into a pattern string of `O`
 *     (looks like an option), `A` (looks like a value) and `-` (the `--`
 *     separator); everything after `--` is forced to `A`.
 *   - An option taking one value matches the pattern `(A)` — with the `-`
 *     characters stripped precisely because `--` may not be swallowed as a
 *     value. That is why `--b -- --c y` reports `argument --b: expected one
 *     argument` rather than treating `--` as `--b`'s value.
 *   - Anything that starts with `-`, is not a known option and looks like a
 *     negative number is reclassified as a value, so `--a -5` sets `a="-5"`.
 *   - The missing-required check lives inside `parse_known_args`, while the
 *     unrecognized-argument check happens afterwards in `parse_args`. Hence a
 *     command line with both faults reports the missing options first.
 */
import path from 'node:path';

import { pyMatch } from '../py/regex.mjs';
import { pyRepr } from '../py/text.mjs';
import { ArgumentError, SystemExit } from './errors.mjs';
import { StoreAction, HelpAction } from './actions.mjs';
import { HelpFormatter } from './help-formatter.mjs';

/** `_get_action_name` — how an action is referred to in error messages. */
function actionName(action) {
  if (action === null || action === undefined) return null;
  if (action.optionStrings.length > 0) return action.optionStrings.join('/');
  if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
  if (action.dest !== null && action.dest !== undefined) return action.dest;
  return null;
}

export class ArgumentParser {
  constructor({
    prog = null,
    usage = null,
    description = null,
    epilog = null,
    prefixChars = '-',
    addHelp = true,
    allowAbbrev = true,
