/**
 * Node.js port of `test4.py`:
 *
 *     import argparse
 *     import schedule
 *
 *     parser = argparse.ArgumentParser()
 *     parser.add_argument('--a', type=str, required=True)
 *     parser.add_argument('--b', type=str, required=True)
 *     parser.add_argument('--c', type=str, required=True)
 *     args = parser.parse_args()
 *
 *     job = schedule.every().monday.at(args.a)  # 创建每周一特定时间作业
 *     print(job)
 *
 * `--b` and `--c` are required but unused, exactly as in the original — only
 * `--a` reaches `Job.at()`.
 *
 * Exit codes match the reference build: 0 on success (and for `--help`),
 * 2 for an argparse failure, 1 for an unhandled exception out of `at()`.
 */
import { ArgumentParser, SystemExit, str } from './lib/argparse/index.mjs';
import schedule from './lib/schedule/index.mjs';
import { PyError } from './lib/py/errors.mjs';
import { frame, printTraceback } from './lib/runtime/traceback.mjs';

/** Source line 10 of `test4.py`, echoed by the traceback on failure. */
const SOURCE_LINE = 'job = schedule.every().monday.at(args.a)  # 创建每周一特定时间作业';
/** Column and width of the `^^^^` anchor under that line. */
const ANCHOR_OFFSET = 'job = '.length;
const ANCHOR_LENGTH = 'schedule.every().monday.at(args.a)'.length;

function main() {
  const parser = new ArgumentParser();
  parser.addArgument('--a', { type: str, required: true });
  parser.addArgument('--b', { type: str, required: true });
  parser.addArgument('--c', { type: str, required: true });
  const args = parser.parseArgs();

  const job = schedule.every().monday.at(args.a);
  console.log(String(job));
}

try {
  main();
} catch (err) {
  if (err instanceof SystemExit) {
    // argparse asked to terminate: `--help` exits 0, a usage error exits 2.
    process.exitCode = err.code;
  } else if (err instanceof PyError) {
    // Unhandled Python-level exception, reported the way the frozen build does.
    printTraceback(
      [
        frame('test4.py', 10, '<module>', SOURCE_LINE, ANCHOR_OFFSET, ANCHOR_LENGTH),
        frame('schedule/__init__.py', err.pyLineno ?? 0, err.pyFunction ?? 'at'),
      ],
      err.pyName,
      err.message,
      'test4',
    );
    process.exitCode = 1;
  } else {
    throw err;
  }
}

