/**
 * argparse's `HelpFormatter`.
 *
 * The layout is not cosmetic — it has to come out byte-identical, so the column
 * arithmetic follows the original rather than being re-derived:
 *
 *   action_max_length = max(len(invocation)) + current_indent
 *   help_position     = min(action_max_length + 2, max_help_position=24)
 *   action_width      = help_position - current_indent - 2
 *   help_width        = max(width - help_position, 11)
 *
 * For this parser the longest invocation is `-h, --help` (10), so
 * action_max_length = 12, help_position = 14, and action_width = 10. That is
 * why `-h, --help` is followed by exactly two spaces before its help text, and
 * why `--a A` — which has no help text — gets no padding at all.
 */
import { pyLen, ljust, spaces, wrap } from '../py/text.mjs';
import { getTerminalSize } from '../py/shutil.mjs';

/** Collapses three-or-more newline runs, as argparse does before returning. */
const LONG_BREAK = /\n\n\n+/gu;

class Section {
  constructor(formatter, parent, heading = null) {
    this.formatter = formatter;
    this.parent = parent;
    this.heading = heading;
    this.items = [];
  }

  formatHelp() {
    if (this.parent !== null) this.formatter.indent();
    const itemHelp = this.formatter.joinParts(this.items.map(([fn, args]) => fn(...args)));
    if (this.parent !== null) this.formatter.dedent();

    if (!itemHelp) return '';

    let heading = '';
    if (this.heading !== null && this.heading !== undefined) {
      heading = `${spaces(this.formatter.currentIndent)}${this.heading}:\n`;
    }
    return this.formatter.joinParts(['\n', heading, itemHelp, '\n']);
  }
}

export class HelpFormatter {
  constructor({ prog, indentIncrement = 2, maxHelpPosition = 24, width = null }) {
    this.prog = prog;
    this.indentIncrement = indentIncrement;
    this.maxHelpPosition = maxHelpPosition;
    // argparse: shutil.get_terminal_size().columns - 2
    this.width = width ?? getTerminalSize().columns - 2;

    this.currentIndent = 0;
    this.level = 0;
    this.actionMaxLength = 0;

    this.rootSection = new Section(this, null);
    this.currentSection = this.rootSection;
  }

  // --- indentation ---------------------------------------------------------

  indent() {
    this.currentIndent += this.indentIncrement;
    this.level += 1;
  }

  dedent() {
    this.currentIndent -= this.indentIncrement;
    this.level -= 1;
  }

  joinParts(parts) {
    return parts.filter(part => part !== null && part !== undefined && part !== '').join('');
  }

  // --- section building ----------------------------------------------------

  addItem(fn, args) {
    this.currentSection.items.push([fn, args]);
  }

  startSection(heading) {
    this.indent();
    const section = new Section(this, this.currentSection, heading);
    this.addItem(() => section.formatHelp(), []);
    this.currentSection = section;
  }

  endSection() {
    this.currentSection = this.currentSection.parent;
    this.dedent();
  }

  addText(text) {
    if (text === null || text === undefined) return;
    this.addItem(t => this.formatText(t), [text]);
  }

  addUsage(usage, actions, prefix = null) {
    this.addItem(
      (u, a, p) => this.formatUsage(u, a, p),
      [usage, actions, prefix],
    );
  }

  addArguments(actions) {
    for (const action of actions) {
      if (action.help === '<SUPPRESS>') continue;
      const invocationLength = pyLen(this.formatActionInvocation(action));
      const actionLength = invocationLength + this.currentIndent;
      this.actionMaxLength = Math.max(this.actionMaxLength, actionLength);
      this.addItem(a => this.formatAction(a), [action]);
    }
  }

  // --- rendering -----------------------------------------------------------

  formatHelp() {
    let help = this.rootSection.formatHelp();
    if (help) {
      help = help.replace(LONG_BREAK, '\n\n');
      help = `${help.replace(/^\n+/u, '').replace(/\n+$/u, '')}\n`;
    }
    return help;
  }

  formatText(text) {
    const indent = spaces(this.currentIndent);
    const textWidth = Math.max(this.width - this.currentIndent, 11);
    const lines = wrap(text, textWidth).map(line => indent + line);
    return `${lines.join('\n')}\n\n`;
  }

  /** `'A'` for `--a`: the metavar argparse derives for an optional. */
  defaultMetavarForOptional(action) {
    return action.dest.toUpperCase();
  }

  metavarFor(action) {
    if (action.metavar !== null && action.metavar !== undefined) return action.metavar;
    if (action.choices !== null && action.choices !== undefined) {
      return `{${action.choices.join(',')}}`;
    }
    return this.defaultMetavarForOptional(action);
  }

  /** `_format_args` for the only nargs form this parser uses. */
  formatArgs(action) {
    return this.metavarFor(action);
  }

  /** `-h, --help` / `--a A`. */
  formatActionInvocation(action) {
    if (action.optionStrings.length === 0) return this.metavarFor(action);
    if (action.nargs === 0) return action.optionStrings.join(', ');
    return `${action.optionStrings.join(', ')} ${this.formatArgs(action)}`;
  }

  /** The bracketed fragments that make up the usage line. */
  actionUsageParts(actions) {
    const parts = [];
    for (const action of actions) {
      if (action.help === '<SUPPRESS>') continue;
      if (action.optionStrings.length === 0) {
        parts.push(this.formatArgs(action));
        continue;
      }
      const optionString = action.optionStrings[0];
      let part = action.nargs === 0
        ? optionString
        : `${optionString} ${this.formatArgs(action)}`;
      if (!action.required) part = `[${part}]`;
      parts.push(part);
    }
    return parts;
  }

  formatUsage(usage, actions, prefix) {
    const usagePrefix = prefix ?? 'usage: ';
    const prog = this.prog;
    let rendered;

    if (usage !== null && usage !== undefined) {
      rendered = usage.replace(/%\(prog\)s/gu, prog);
    } else {
      const optionals = actions.filter(a => a.optionStrings.length > 0);
      const positionals = actions.filter(a => a.optionStrings.length === 0);
      const actionUsage = this.actionUsageParts([...optionals, ...positionals]).join(' ');
      rendered = [prog, actionUsage].filter(s => s).join(' ');

      const textWidth = this.width - this.currentIndent;
      if (pyLen(usagePrefix) + pyLen(rendered) > textWidth) {
        const optParts = this.actionUsageParts(optionals);
        const posParts = this.actionUsageParts(positionals);

        const getLines = (parts, indent, linePrefix = null) => {
          const lines = [];
          let line = [];
          let lineLen = (linePrefix !== null ? pyLen(linePrefix) : pyLen(indent)) - 1;
          for (const part of parts) {
            if (lineLen + 1 + pyLen(part) > textWidth && line.length > 0) {
              lines.push(indent + line.join(' '));
              line = [];
              lineLen = pyLen(indent) - 1;
            }
            line.push(part);
            lineLen += 1 + pyLen(part);
          }
          if (line.length > 0) lines.push(indent + line.join(' '));
          if (linePrefix !== null && lines.length > 0) {
            lines[0] = lines[0].slice(indent.length);
          }
          return lines;
        };

        let lines;
        if (pyLen(usagePrefix) + pyLen(prog) <= 0.75 * textWidth) {
          const indent = spaces(pyLen(usagePrefix) + pyLen(prog) + 1);
          if (optParts.length > 0) {
            lines = getLines([prog, ...optParts], indent, usagePrefix);
            lines.push(...getLines(posParts, indent));
          } else if (posParts.length > 0) {
            lines = getLines([prog, ...posParts], indent, usagePrefix);
          } else {
            lines = [prog];
          }
        } else {
          const indent = spaces(pyLen(usagePrefix));
          lines = getLines([...optParts, ...posParts], indent);
          if (lines.length > 1) {
            lines = [...getLines(optParts, indent), ...getLines(posParts, indent)];
          }
          lines = [prog, ...lines];
        }
        rendered = lines.join('\n');
      }
    }

    return `${usagePrefix}${rendered}\n\n`;
  }

  formatAction(action) {
    const helpPosition = Math.min(this.actionMaxLength + 2, this.maxHelpPosition);
    const helpWidth = Math.max(this.width - helpPosition, 11);
    const actionWidth = helpPosition - this.currentIndent - 2;

    const header = this.formatActionInvocation(action);
    let actionHeader;
    let indentFirst = 0;

    if (!action.help) {
      // No help text: the invocation stands alone, unpadded.
      actionHeader = `${spaces(this.currentIndent)}${header}\n`;
    } else if (pyLen(header) <= actionWidth) {
      actionHeader = `${spaces(this.currentIndent)}${ljust(header, actionWidth)}  `;
      indentFirst = 0;
    } else {
      actionHeader = `${spaces(this.currentIndent)}${header}\n`;
      indentFirst = helpPosition;
    }

    const parts = [actionHeader];
    if (action.help && action.help.trim()) {
      const helpLines = wrap(action.help, helpWidth);
      parts.push(`${spaces(indentFirst)}${helpLines[0]}\n`);
      for (const line of helpLines.slice(1)) {
        parts.push(`${spaces(helpPosition)}${line}\n`);
      }
    } else if (!actionHeader.endsWith('\n')) {
      parts.push('\n');
    }

    return this.joinParts(parts);
  }
}

