#!/usr/bin/env node
/* Exhaustive Unicode Nd sweep: every Nd code point in every digit position. */
import { spawnSync } from 'node:child_process';

const EXE = '/workspace/dataset/test4_executable';
const JS = '/output/test4.mjs';

const nd = [];
for (let cp = 0; cp <= 0x10ffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  const ch = String.fromCodePoint(cp);
  if (/^\p{Nd}$/u.test(ch)) nd.push(ch);
}
process.stderr.write(`Nd code points: ${nd.length}\n`);

function run(cmd, args, value) {
  const r = spawnSync(cmd, [...args, '--a', value, '--b', 'x', '--c', 'y'], {
    cwd: '/tmp', encoding: 'buffer',
  });
  const err = r.stderr.toString('utf8');
  let kind = 'ok';
  if (r.status !== 0) {
    if (err.includes('Invalid time format')) kind = 'format';
    else if (err.includes('Invalid number of hours')) kind = 'hours';
    else kind = `other:${err.split('\n').filter(Boolean).pop()}`;
  }
  return { code: r.status, out: r.stdout.toString('utf8'), kind };
}

// Each template has one '@' placeholder for the digit under test.
const TEMPLATES = ['@0:30', '1@:30', '10:@0', '10:3@', '2@:30', '@:30', '10:30:@0', '10:30:3@'];

let compared = 0;
const mismatches = [];
for (const tpl of TEMPLATES) {
  for (const ch of nd) {
    const value = tpl.replace('@', ch);
    const a = run(EXE, [], value);
    const b = run('node', [JS], value);
    compared += 1;
    if (a.code !== b.code || a.out !== b.out || a.kind !== b.kind) {
      mismatches.push({
        tpl,
        cp: `U+${ch.codePointAt(0).toString(16).toUpperCase()}`,
        ref: a, port: b,
      });
    }
  }
  process.stderr.write(`  ${tpl}: done (${compared} compared, ${mismatches.length} mismatches)\n`);
}

console.log(`\nTOTAL compared: ${compared}`);
console.log(`MISMATCHES: ${mismatches.length}`);
for (const m of mismatches.slice(0, 40)) {
  console.log(`  ${m.tpl} ${m.cp}: ref=${m.ref.code}/${m.ref.kind} port=${m.port.code}/${m.port.kind}`);
}

