toolUseResult.originalFile:
/**
 * Bridging Python `re` semantics onto JavaScript `RegExp`.
 *
 * Two differences bite when porting the patterns used by `schedule` and
 * `argparse`:
 *
 *   1. `\d` — Python matches any Unicode decimal digit (category Nd);
 *      JavaScript's `\d` is `[0-9]`. Translated to `\p{Nd}`.
 *   2. `$` — Python's `$` matches at the end of the string *or immediately
 *      before a single trailing newline*; JavaScript's `$` (without `m`) only
 *      matches at the very end. Translated to `\n?$`.
 *
 * Consequence of (2), verified against the reference implementation:
 * `"10:30\n"` is an accepted time string, while `"10:30\n\n"` is not.
 *
 * `translatePattern` deliberately handles only the constructs used by this
 * port (character classes, groups, `\d`, `^`, `$`, `?`); it is not a general
 * Python-to-JavaScript regex compiler.
 */

/** Translate a Python pattern source into JavaScript pattern source. */
export function translatePattern(source) {
  let out = '';
  let inClass = false;
  for (let i = 0; i < source.length; i += 1) {
    const ch = source[i];
    if (ch === '\\') {
      const next = source[i + 1];
      if (next === 'd') {
        out += '\\p{Nd}';
        i += 1;
        continue;
      }
      out += ch + (next ?? '');
      i += 1;
      continue;
    }
    if (ch === '[') inClass = true;
    else if (ch === ']') inClass = false;
    else if (ch === '$' && !inClass && i === source.length - 1) {
      // Trailing `$`: allow one optional newline, as Python does.
      out += '\\n?$';
      continue;
    }
    out += ch;
  }
  return out;
}

/** Compile a Python pattern into a `RegExp` with Unicode semantics. */
export function pyCompile(source, flags = '') {
  return new RegExp(translatePattern(source), `${flags}u`);
}

/**
 * Equivalent of `re.match(pattern, s)` — anchored at the start of the string,
 * not required to reach the end. Returns the match object or `null`.
 */
export function pyMatch(source, s) {
  const translated = translatePattern(source);
  const anchored = translated.startsWith('^') ? translated : `^(?:${translated})`;
  return new RegExp(anchored, 'u').exec(s);
}

