/**
 * The sliver of `datetime` that `schedule` depends on.
 *
 * `Job.at()` finishes by building a `datetime.time`, so the port needs a value
 * object with the same construction-time range validation. Nothing prints it,
 * but keeping the check means an out-of-range component surfaces the same
 * ValueError it would in Python instead of being silently accepted.
 */
import { PyValueError } from './errors.mjs';
import { pyInt } from './int.mjs';

const RANGES = [
  ['hour', 0, 23],
  ['minute', 0, 59],
  ['second', 0, 59],
  ['microsecond', 0, 999999],
];

export class PyTime {
  constructor(hour = 0, minute = 0, second = 0, microsecond = 0) {
    const values = [hour, minute, second, microsecond].map(pyInt);
    values.forEach((value, index) => {
      const [name, low, high] = RANGES[index];
      if (value < low || value > high) {
        throw new PyValueError(`${name} must be in ${low}..${high}`);
      }
    });
    [this.hour, this.minute, this.second, this.microsecond] = values;
  }

  /** `str(datetime.time)` — ISO 8601, dropping a zero microsecond field. */
  toString() {
    const pad = (n, width) => String(n).padStart(width, '0');
    const base = `${pad(this.hour, 2)}:${pad(this.minute, 2)}:${pad(this.second, 2)}`;
    return this.microsecond === 0 ? base : `${base}.${pad(this.microsecond, 6)}`;
  }
}

/** `datetime.time(...)`. */
export function time(hour, minute, second, microsecond) {
  return new PyTime(hour, minute, second, microsecond);
}

/**
 * The `Job` object returned by `schedule.every()`.
 *
 * Only the surface `test4.py` touches is modelled: the `interval`/`unit`/
 * `start_day` state built up by the day-name properties, the `at()` validator,
 * and `__str__`.
 *
 * The two line numbers below are the positions the reference build reports in
 * its traceback for the two failure paths inside `at()`. They are recorded on
 * the raised error so the traceback renderer can reproduce the frame.
 */
import { PyTypeError } from '../py/errors.mjs';
import { pyInt } from '../py/int.mjs';
import { pyMatch } from '../py/regex.mjs';
import { pyRepr, pyStr } from '../py/text.mjs';
import { time } from '../py/datetime.mjs';
import { ScheduleValueError, IntervalError } from './errors.mjs';

/** `schedule/__init__.py` line of the `at()` time-format raise. */
const LINENO_FORMAT = 514;
/** `schedule/__init__.py` line of the `at()` hour-range raise. */
const LINENO_HOURS = 547;

const DAY_NAMES = [
  'monday', 'tuesday', 'wednesday', 'thursday',
  'friday', 'saturday', 'sunday',
];

function at(lineno, error) {
  error.pyLineno = lineno;
  error.pyFunction = 'at';
  return error;
}

export class Job {
  constructor(interval, scheduler = null) {
    this.interval = interval;
    this.latest = null;
    this.jobFunc = null;
    this.unit = null;
    this.atTime = null;
    this.atTimeZone = null;
    this.lastRun = null;
    this.nextRun = null;
    this.period = null;
    this.startDay = null;
    this.cancelAfter = null;
    this.tags = new Set();
    this.scheduler = scheduler;
  }

  // --- unit properties -----------------------------------------------------

  get second() {
    if (this.interval !== 1) {
      throw new IntervalError('Use seconds instead of second');
    }
    return this.seconds;
  }

  get seconds() {
    this.unit = 'seconds';
    return this;
  }

  get minute() {
    if (this.interval !== 1) {
      throw new IntervalError('Use minutes instead of minute');
    }
    return this.minutes;
  }

  get minutes() {
    this.unit = 'minutes';
    return this;
  }

  get hour() {
    if (this.interval !== 1) {
      throw new IntervalError('Use hours instead of hour');
    }
    return this.hours;
  }

  get hours() {
    this.unit = 'hours';
    return this;
  }

  get day() {
    if (this.interval !== 1) {
      throw new IntervalError('Use days instead of day');
    }
    return this.days;
  }

  get days() {
    this.unit = 'days';
    return this;
  }

  get week() {
    if (this.interval !== 1) {
      throw new IntervalError('Use weeks instead of week');
    }
    return this.weeks;
  }

  get weeks() {
    this.unit = 'weeks';
    return this;
  }

  /**
   * Pin a weekly job to a given weekday. `schedule` exposes one property per
   * day name; they all funnel through here.
   */
  onWeekday(dayName) {
    if (this.interval !== 1) {
      throw new IntervalError(
        `Scheduling .${dayName}() jobs is only allowed for weekly jobs. `
        + `Using .${dayName}() on a job scheduled to run every 2 or more weeks `
        + 'is not supported.',
      );
    }
    this.startDay = dayName;
    return this.weeks;
  }

  // --- time-of-day validation ---------------------------------------------

  /**
   * `Job.at(time_str)`.
   *
   * For a job with a `start_day` (the weekly case), the accepted format is the
   * daily one: `HH:MM` or `HH:MM:SS`. Two details of the reference behaviour
   * are load-bearing and are reproduced exactly:
   *
   *   - The pattern only constrains the hour's *first* digit to 0-2, so 24..29
   *     pass the format check and are rejected afterwards by the range check
   *     with a different message.
   *   - That range-check message is emitted verbatim, braces and all. The
   *     reference build never interpolates the offending value, so the text
   *     really is `Invalid number of hours ({} is not between 0 and 23)`.
   */
  at(timeStr, tz = null) {
    if (!['days', 'hours', 'minutes'].includes(this.unit) && !this.startDay) {
      throw new ScheduleValueError(
        'Invalid unit (valid units are `days`, `hours`, and `minutes`)',
      );
    }

    if (tz !== null && tz !== undefined) {
      // The reference resolves this through pytz, which has no counterpart
      // here. `test4.py` never passes a timezone.
      throw new ScheduleValueError(
        'Timezone support is not available in this port of schedule.at()',
      );
    }

    if (typeof timeStr !== 'string') {
      throw new PyTypeError('at() should be passed a string');
    }

    if (this.unit === 'days' || this.startDay) {
      if (!pyMatch(String.raw`^[0-2]\d:[0-5]\d(:[0-5]\d)?$`, timeStr)) {
        throw at(LINENO_FORMAT, new ScheduleValueError(
          'Invalid time format for a daily job (valid format is HH:MM(:SS)?)',
        ));
      }
    }
    if (this.unit === 'hours') {
      if (!pyMatch(String.raw`^([0-5]\d)?:[0-5]\d$`, timeStr)) {
        throw at(LINENO_FORMAT, new ScheduleValueError(
          'Invalid time format for an hourly job (valid format is (MM)?:SS)',
        ));
      }
    }
    if (this.unit === 'minutes') {
      if (!pyMatch(String.raw`^:[0-5]\d$`, timeStr)) {
        throw at(LINENO_FORMAT, new ScheduleValueError(
          'Invalid time format for a minutely job (valid format is :SS)',
        ));
      }
    }

    const timeValues = timeStr.split(':');
    let hour;
    let minute;
    let second;
    if (timeValues.length === 3) {
      [hour, minute, second] = timeValues;
    } else if (timeValues.length === 2 && this.unit === 'minutes') {
      hour = 0;
      minute = 0;
      [, second] = timeValues;
    } else if (
      timeValues.length === 2 && this.unit === 'hours' && timeValues[0].length
    ) {
      hour = 0;
      [minute, second] = timeValues;
    } else {
      [hour, minute] = timeValues;
      second = 0;
    }

    if (this.unit === 'days' || this.startDay) {
      hour = pyInt(hour);
      if (!(hour >= 0 && hour <= 23)) {
        throw at(LINENO_HOURS, new ScheduleValueError(
          'Invalid number of hours ({} is not between 0 and 23)',
        ));
      }
    } else if (this.unit === 'hours') {
      hour = 0;
    } else if (this.unit === 'minutes') {
      hour = 0;
      minute = 0;
    }
    minute = pyInt(minute);
    second = pyInt(second);
    this.atTime = time(hour, minute, second);
    return this;
  }

  // --- rendering -----------------------------------------------------------

  /**
   * `Job.__str__`, which is what `print(job)` reaches.
   *
   * With no work attached, `job_func` is `None`: `do` renders as `repr(None)`
   * and the argument fields fall back to the literal `()` and `{}`.
   */
  toString() {
    const jobFuncName = this.jobFunc && this.jobFunc.name
      ? this.jobFunc.name
      : pyRepr(this.jobFunc);
    const args = this.jobFunc === null ? '()' : this.jobFunc.args;
    const kwargs = this.jobFunc === null ? '{}' : this.jobFunc.keywords;
    return `Job(interval=${pyStr(this.interval)}, unit=${pyStr(this.unit)}, `
      + `do=${jobFuncName}, args=${args}, kwargs=${kwargs})`;
  }
}

/** Install `job.monday` … `job.sunday` as properties, as `schedule` does. */
for (const dayName of DAY_NAMES) {
  Object.defineProperty(Job.prototype, dayName, {
    get() {
      return this.onWeekday(dayName);
    },
  });
}

export { DAY_NAMES };

