3	 *
4	 * The layout is not cosmetic — it has to come out byte-identical, so the column
5	 * arithmetic follows the original rather than being re-derived:
6	 *
7	 *   action_max_length = max(len(invocation)) + current_indent
8	 *   help_position     = min(action_max_length + 2, max_help_position=24)
9	 *   action_width      = help_position - current_indent - 2
10	 *   help_width        = max(width - help_position, 11)
11	 *
12	 * For this parser the longest invocation is `-h, --help` (10), so at the default
13	 * width action_max_length = 12, help_position = 14, and action_width = 10. That
14	 * is why `-h, --help` is followed by exactly two spaces before its help text,
15	 * and why `--a A` — which has no help text — gets no padding at all.
16	 *
17	 * `max_help_position` is itself clamped against the terminal width by
18	 *
19	 *   max_help_position = min(24, max(width - 20, indent_increment * 2))
20	 *
21	 * which has no effect at the default width but takes over on a narrow
22	 * terminal: once help_position drops below the length of `-h, --help`, the
23	 * invocation moves onto its own line and the help text is indented beneath it.
24	 */
25	import { pyLen, ljust, spaces, wrap } from '../py/text.mjs';
26	import { getTerminalSize } from '../py/shutil.mjs';
27	import { SUPPRESS } from './actions.mjs';
28	
29	/** Collapses three-or-more newline runs, as argparse does before returning. */
30	const LONG_BREAK = /\n\n\n+/gu;
31	
32	class Section {
33	  constructor(formatter, parent, heading = null) {
34	    this.formatter = formatter;
35	    this.parent = parent;
36	    this.heading = heading;
37	    this.items = [];
38	  }
39	
40	  formatHelp() {
41	    if (this.parent !== null) this.formatter.indent();
42	    const itemHelp = this.formatter.joinParts(this.items.map(([fn, args]) => fn(...args)));
43	    if (this.parent !== null) this.formatter.dedent();
44	
45	    if (!itemHelp) return '';
46	
47	    let heading = '';
48	    if (this.heading !== null && this.heading !== undefined) {
49	      heading = `${spaces(this.formatter.currentIndent)}${this.heading}:\n`;
50	    }
51	    return this.formatter.joinParts(['\n', heading, itemHelp, '\n']);
52	  }
53	}
