56	  constructor({ prog, indentIncrement = 2, maxHelpPosition = 24, width = null }) {
57	    this.prog = prog;
58	    this.indentIncrement = indentIncrement;
59	    // argparse: shutil.get_terminal_size().columns - 2
60	    this.width = width ?? getTerminalSize().columns - 2;
61	    this.maxHelpPosition = Math.min(
62	      maxHelpPosition,
63	      Math.max(this.width - 20, indentIncrement * 2),
64	    );
65	
66	    this.currentIndent = 0;
67	    this.level = 0;
68	    this.actionMaxLength = 0;
69	
70	    this.rootSection = new Section(this, null);
71	    this.currentSection = this.rootSection;
72	  }
